const TexasHoldemPvpGameModal = ({ visible, onClose, room, playerId, playerName }: { visible: boolean; onClose: () => void; room: any; playerId: string; playerName: string }) => {
  const webRef = useRef<any>(null);
  const lastRoomRef = useRef<string>('');
  const settleDoneRef = useRef(false);
  const [pvpError, setPvpError] = useState('');
  const me = playerId;
  const hostId = room?.host_id;
  const guestId = room?.guest_id;
  const foeId = me === hostId ? (guestId || '') : (hostId || '');
  const foeName = me === hostId ? (room?.guest_name || 'Player') : (room?.host_name || 'Player');
  const code = room?.code;
  const myIndex = me === hostId ? 0 : 1;
  useEffect(() => {
    if (!visible || !code) return;
    const poll = async () => {
      try {
        const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/' + code + '?player_id=' + encodeURIComponent(me));
        if (!res.ok) return;
        const data = await res.json();
        const js = JSON.stringify(data);
        if (js !== lastRoomRef.current) {
          lastRoomRef.current = js;
          if (webRef.current) {
            webRef.current.injectJavaScript('window.dispatchEvent(new CustomEvent("texas-holdem-room", {detail: ' + js + '})); true;');
            if (data.wager_status === 'held' && data.state && data.state.sessionOver === true && typeof data.state.sessionWinner === 'number') { settleWagerTexas(data.state.sessionWinner); }
          }
        }
      } catch (e) {}
    };
    poll();
    const t = setInterval(poll, 2000);
    return () => clearInterval(t);
  }, [visible, code]);
  useEffect(() => {
    if (!visible || !code || room?.wager_status !== 'agreed') return;
    const startWager = async () => {
      try {
        const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/rooms/' + code + '/wager/start', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ player_id: me }) });
        if (!res.ok) { const d = await res.json().catch(() => ({})); if (d?.detail) setPvpError(d.detail); }
      } catch (e) {}
    };
    startWager();
  }, [visible, code]);
  const settleWagerTexas = async (sessionWinnerIdx: number) => {
    if (settleDoneRef.current) return;
    settleDoneRef.current = true;
    const winId = sessionWinnerIdx === 0 ? hostId : guestId;
    try { await fetch(TH_API_BASE + '/api/texas_holdem/rooms/rooms/' + code + '/wager/settle', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ player_id: me, outcome: 'win', winner_id: winId }) }); } catch (e) {}
  };
  const handlePvpMessage = async (event: any) => {
    const raw = event?.nativeEvent?.data;
    if (raw === 'close') { onClose(); return; }
    try {
      const msg = JSON.parse(raw);
      if (msg?.type === 'texas-holdem-state' && msg.state) {
        const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/' + code + '/state', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ player_id: me, state: msg.state, status: msg.status || msg.state.status || '', winner: msg.winner || '', new_hand: msg.new_hand || false }),
        });
        if (!res.ok) {
          const d = await res.json().catch(() => ({}));
          setPvpError(d?.detail || 'Could not send your move.');
        } else {
          setPvpError('');
          const data = await res.json().catch(() => null);
          if (data) lastRoomRef.current = JSON.stringify(data);
          if (msg.state && msg.state.sessionOver === true && typeof msg.state.sessionWinner === 'number') { settleWagerTexas(msg.state.sessionWinner); }
        }
      } else if (msg?.type === 'texas-holdem-chat' && msg.text) {
        const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/' + code + '/chat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ player_id: me, player_name: playerName, text: msg.text }),
        });
        if (res.ok) {
          const data = await res.json().catch(() => null);
          if (data) lastRoomRef.current = JSON.stringify(data);
        }
      } else if (msg?.type === 'texas-holdem-leave') {
        try { await fetch(TH_API_BASE + '/api/texas_holdem/rooms/' + code + '/leave', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ player_id: me }) }); } catch (e) {}
        onClose();
      }
    } catch (e) {}
  };
  const pvpConfig = 'window.TEXAS_HOLDEM_ROOM = ' + JSON.stringify({ me: me, foe: foeId, foeName: foeName, hostId: hostId, myIndex: myIndex }) + '; true;';
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      <View style={{ flex: 1, backgroundColor: '#111111' }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 12 }}>
          <Text style={{ color: '#ffffff', fontWeight: '800', fontSize: 16 }}>TEXAS HOLD&apos;EM - YOU vs {foeName}</Text>
          <TouchableOpacity onPress={onClose} style={{ backgroundColor: '#e74c3c', paddingVertical: 8, paddingHorizontal: 14, borderRadius: 8 }}>
            <Text style={{ color: '#ffffff', fontWeight: '800' }}>CLOSE</Text>
          </TouchableOpacity>
        </View>
        {pvpError ? (<Text style={{ color: '#ff6666', textAlign: 'center', fontSize: 12, marginBottom: 6 }}>{pvpError}</Text>) : null}
        {PoolWebView ? (
          <PoolWebView
            source={{ html: TEXAS_HOLDEM_PVP_HTML }}
            injectedJavaScriptBeforeContentLoaded={pvpConfig}
            injectedJavaScript={pvpConfig + '/* PVP_ALL_TEXAS_REAPPLY */'}
            javaScriptEnabled={true}
            domStorageEnabled={true}
            allowsInlineMediaPlayback={true}
            mediaPlaybackRequiresUserAction={false}
            originWhitelist={['*']}
            style={{ flex: 1 }}
            ref={webRef}
            onMessage={handlePvpMessage}
          />
        ) : (
          <Text style={{ color: '#ffffff', textAlign: 'center', marginTop: 40 }}>Texas Hold&apos;em needs WebView, which is not available in this build.</Text>
        )}
      </View>
    </Modal>
  );
};

// WAGER_TEXAS_HOLDEM_FRONTEND_V1
const TexasHoldemPvpModal = ({ visible, onClose, playerId, playerName, room, setRoom, onPlay, onLeave }: { visible: boolean; onClose: () => void; playerId: string; playerName: string; room: any; setRoom: (r: any) => void; onPlay: () => void; onLeave: () => void }) => {
  const [codeInput, setCodeInput] = useState('');
  const [chatInput, setChatInput] = useState('');
  const [info, setInfo] = useState('');
  const [busy, setBusy] = useState(false);
  // PVP_ALL_REJOIN_TEXAS: offer the player's live room back after a boot-out.
  const [activeRoomTexas, setActiveRoomTexas] = useState<any | null>(null);
  useEffect(() => {
    if (!visible || room) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/active/' + playerId);
        if (!cancelled && res.ok) { const d = await res.json(); setActiveRoomTexas(d); }
        else if (!cancelled) { setActiveRoomTexas(null); }
      } catch (e) { if (!cancelled) setActiveRoomTexas(null); }
    })();
    return () => { cancelled = true; };
  }, [visible, room?.code]);
  const [wagerAmount, setWagerAmount] = useState('');
  const [wagerInfo, setWagerInfo] = useState('');
  const wagerPost = async (action: string, body: any) => {
    if (!room?.code) return null;
    try {
      const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/rooms/' + room.code + '/wager/' + action, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) { setWagerInfo(data?.detail || 'Wager request failed.'); return null; }
      setRoom(data); return data;
    } catch (e) { setWagerInfo('Wager rooms are not live yet - the backend still needs a Deploy.'); return null; }
  };
  const proposeWager = async () => {
    const amount = parseInt(wagerAmount, 10);
    if (!amount || amount <= 0) { setWagerInfo('Enter a cash amount above 0.'); return; }
    setWagerInfo('');
    const data = await wagerPost('propose', { player_id: playerId, amount: amount });
    if (data) setWagerInfo('Wager proposed: $' + amount + '. Waiting for your friend to agree.');
  };
  const agreeWager = async () => {
    setWagerInfo('');
    const data = await wagerPost('agree', { player_id: playerId });
    if (data) setWagerInfo('Wager agreed: $' + data.wager_amount + '. Cash is taken when the game starts.');
  };
  const declineWager = async () => {
    setWagerInfo('');
    await wagerPost('decline', { player_id: playerId });
  };
  const showNotLive = () => setInfo('Texas Holdem rooms are not live yet - the backend still needs a Deploy that picks up the rooms code.');
  const createRoom = async () => {
    setBusy(true); setInfo('');
    try {
      const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/create', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ player_id: playerId, player_name: playerName }) });
      if (res.status === 404) { showNotLive(); return; }
      if (!res.ok) { const d = await res.json().catch(() => ({})); setInfo(d?.detail || 'Could not create a room.'); return; }
      const data = await res.json();
      setRoom(data);
      setInfo('Room ' + data.code + ' created. Share the code with your friend.');
    } catch (e) { showNotLive(); } finally { setBusy(false); }
  };
  const joinRoom = async () => {
    const code = codeInput.trim();
    if (code.length !== 4) { setInfo('Enter the 4-digit room code.'); return; }
    setBusy(true); setInfo('');
    try {
      const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/join', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ code: code, player_id: playerId, player_name: playerName }) });
      if (res.status === 404) { showNotLive(); return; }
      if (!res.ok) { const d = await res.json().catch(() => ({})); setInfo(d?.detail || 'Could not join the room.'); return; }
      const data = await res.json();
      setRoom(data);
      // PVP_ALL_AUTOPLAY_JOIN_TEXAS: game opens on successful join.
      onPlay();
    } catch (e) { showNotLive(); } finally { setBusy(false); }
  };
  const sendChat = async () => {
    if (!room?.code || !chatInput.trim()) return;
    const text = chatInput.trim();
    setChatInput('');
    try {
      const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/' + room.code + '/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ player_id: playerId, player_name: playerName, text: text }) });
      if (res.ok) { const data = await res.json(); setRoom(data); }
    } catch (e) {}
  };
  useEffect(() => {
    if (!visible || !room?.code) return;
    const poll = async () => {
      try {
        const res = await fetch(TH_API_BASE + '/api/texas_holdem/rooms/' + room.code + '?player_id=' + encodeURIComponent(playerId));
        if (res.ok) { const data = await res.json(); setRoom(data); }
      } catch (e) {}
    };
    const t = setInterval(poll, 2000);
    return () => clearInterval(t);
  }, [visible, room?.code]);
  const foeName = room ? (playerId === room.host_id ? (room.guest_name || 'Friend') : (room.host_name || 'Friend')) : '';
  const canPlay = room && room.status === 'playing';
  // PVP_ALL_AUTOPLAY_HOST_TEXAS: host's game opens on waiting->playing flip.
  const prevStatusRefTexas = useRef<string>(room?.status || '');
  useEffect(() => {
    const prev = prevStatusRefTexas.current;
    prevStatusRefTexas.current = room?.status || '';
    if (room?.status === 'playing' && prev === 'waiting') { onPlay(); }
  }, [room?.status]);
  return (
    <Modal visible={visible} animationType="slide" onRequestClose={onClose}>
      <View style={{ flex: 1, backgroundColor: '#111111', padding: 16 }}>
        <Text style={{ color: '#ffffff', fontWeight: '800', fontSize: 18, textAlign: 'center', marginBottom: 4 }}>TEXAS HOLD&apos;EM - PLAYER VS PLAYER</Text>
        {info ? (<Text style={{ color: '#f39c12', fontSize: 12, textAlign: 'center', marginBottom: 12 }}>{info}</Text>) : null}
        {!room ? (
          <View>
            <Text style={{ color: '#cccccc', fontSize: 13, textAlign: 'center', marginBottom: 12 }}>Heads-up No-Limit Texas Hold&apos;em. The host deals the first hand as button / small blind.</Text>
            {activeRoomTexas ? (
              <TouchableOpacity onPress={() => { setRoom(activeRoomTexas); if (activeRoomTexas.status === 'playing') { onPlay(); } }} style={{ backgroundColor: '#f39c12', paddingVertical: 12, borderRadius: 8, marginBottom: 12 }}>
                <Text style={{ color: '#111111', fontWeight: '800', textAlign: 'center' }}>REJOIN ROOM {activeRoomTexas.code}</Text>
              </TouchableOpacity>
            ) : null}
            <TouchableOpacity onPress={createRoom} disabled={busy} style={{ backgroundColor: '#2e7d32', paddingVertical: 12, borderRadius: 8, marginBottom: 12 }}>
              <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>CREATE ROOM</Text>
            </TouchableOpacity>
            <Text style={{ color: '#cccccc', fontSize: 12, textAlign: 'center', marginBottom: 6 }}>Or join a friend&apos;s room (uses the host&apos;s game):</Text>
            <TextInput value={codeInput} onChangeText={setCodeInput} keyboardType="number-pad" maxLength={4} placeholder="4-digit code" placeholderTextColor="#888888" style={{ backgroundColor: '#222222', color: '#ffffff', padding: 12, borderRadius: 8, marginBottom: 10, textAlign: 'center', fontSize: 18, fontWeight: '800' }} />
            <TouchableOpacity onPress={joinRoom} disabled={busy} style={{ backgroundColor: '#1e88e5', paddingVertical: 12, borderRadius: 8, marginBottom: 12 }}>
              <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>JOIN ROOM</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={onClose} style={{ backgroundColor: '#666666', paddingVertical: 12, borderRadius: 8, marginTop: 12 }}>
              <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>CANCEL</Text>
            </TouchableOpacity>
          </View>
        ) : (
          <View style={{ flex: 1 }}>
            <Text style={{ color: '#ffffff', fontWeight: '800', fontSize: 28, textAlign: 'center' }}>Room {room.code}</Text>
            <Text style={{ color: '#cccccc', fontSize: 12, textAlign: 'center', marginBottom: 12 }}>
              {room.status === 'waiting' ? 'Waiting for your friend to join...' : room.status === 'playing' ? (foeName + ' joined!') : 'Game over.'}
            </Text>
            {room && room.status !== 'finished' ? (
              <View style={{ backgroundColor: '#1a1a1a', borderRadius: 8, padding: 10, marginBottom: 12 }}>
                <Text style={{ color: '#ffffff', fontWeight: '800', marginBottom: 6 }}>💰 CASH WAGER - Street Legends cash, not real money</Text>
                {room.wager_status === 'held' ? (
                  <Text style={{ color: '#f39c12', fontSize: 13 }}>Wager held: ${room.wager_amount} each. Winner takes ${room.wager_amount * 2}.</Text>
                ) : room.wager_status === 'agreed' ? (
                  <Text style={{ color: '#f39c12', fontSize: 13 }}>Wager agreed: ${room.wager_amount}. Cash is taken from both players when the game starts.</Text>
                ) : room.wager_status === 'proposed' ? (
                  playerId === room.host_id ? (
                    <Text style={{ color: '#cccccc', fontSize: 13 }}>Wager proposed: ${room.wager_amount}. Waiting for {foeName} to agree or decline.</Text>
                  ) : (
                    <View>
                      <Text style={{ color: '#ffffff', fontSize: 13, marginBottom: 6 }}>{foeName} proposes a ${room.wager_amount} cash wager. Make sure you have at least that much cash before agreeing.</Text>
                      <View style={{ flexDirection: 'row', gap: 8 }}>
                        <TouchableOpacity onPress={agreeWager} style={{ flex: 1, backgroundColor: '#2e7d32', paddingVertical: 10, borderRadius: 8 }}>
                          <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>AGREE</Text>
                        </TouchableOpacity>
                        <TouchableOpacity onPress={declineWager} style={{ flex: 1, backgroundColor: '#666666', paddingVertical: 10, borderRadius: 8 }}>
                          <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>DECLINE</Text>
                        </TouchableOpacity>
                      </View>
                    </View>
                  )
                ) : room.wager_status === 'paid' ? (
                  <Text style={{ color: '#2e7d32', fontSize: 13, fontWeight: '800' }}>{room.wager_winner_id === playerId ? ('You won the wager: $' + (room.wager_amount * 2) + ' cash!') : (foeName + ' won the wager.')}</Text>
                ) : room.wager_status === 'refunded' ? (
                  <Text style={{ color: '#cccccc', fontSize: 13 }}>Wager refunded - the game was a draw.</Text>
                ) : playerId === room.host_id ? (
                  <View>
                    <Text style={{ color: '#cccccc', fontSize: 12, marginBottom: 6 }}>Propose a cash wager. Both players must agree, and both need at least this much cash.</Text>
                    <View style={{ flexDirection: 'row', gap: 8 }}>
                      <TextInput value={wagerAmount} onChangeText={setWagerAmount} keyboardType="number-pad" placeholder="Cash amount" placeholderTextColor="#888888" style={{ flex: 1, backgroundColor: '#222222', color: '#ffffff', padding: 10, borderRadius: 8 }} />
                      <TouchableOpacity onPress={proposeWager} style={{ backgroundColor: '#2e7d32', paddingVertical: 10, paddingHorizontal: 16, borderRadius: 8 }}>
                        <Text style={{ color: '#ffffff', fontWeight: '800' }}>PROPOSE</Text>
                      </TouchableOpacity>
                    </View>
                  </View>
                ) : (
                  <Text style={{ color: '#cccccc', fontSize: 13 }}>No wager yet - the host can propose one.</Text>
                )}
                {wagerInfo ? (<Text style={{ color: '#f39c12', fontSize: 12, marginTop: 6 }}>{wagerInfo}</Text>) : null}
              </View>
            ) : null}

            {canPlay ? (
              <TouchableOpacity onPress={onPlay} style={{ backgroundColor: '#2e7d32', paddingVertical: 12, borderRadius: 8, marginBottom: 12 }}>
                <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>PLAY</Text>
              </TouchableOpacity>
            ) : null}
            {/* PVP_ALL_NOCHAT: chat removed */}

            <TouchableOpacity onPress={onClose} style={{ backgroundColor: '#666666', paddingVertical: 12, borderRadius: 8, marginTop: 12 }}>
              <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>BACK</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={onLeave} style={{ backgroundColor: '#e74c3c', paddingVertical: 12, borderRadius: 8, marginTop: 12 }}>
              <Text style={{ color: '#ffffff', fontWeight: '800', textAlign: 'center' }}>LEAVE ROOM</Text>
            </TouchableOpacity>
          </View>
        )}
      </View>
    </Modal>
  );
};

